import { db } from "@/lib/db";
import { formatDate } from "@/lib/utils";
import { PageHeader, Table, td } from "@/components/admin/ui";

export default async function AdminAudit() {
  const logs = await db.auditLog.findMany({ orderBy: { createdAt: "desc" }, take: 300, include: { actor: { select: { name: true } } } });
  return (
    <>
      <PageHeader title="Audit log" description="Every change made in the admin panel, newest first." />
      <div className="rounded-lg border border-line bg-white">
        <Table head={["When", "Who", "Action", "Record", "Details"]}>
          {logs.map((l) => (
            <tr key={l.id}>
              <td className={`${td} whitespace-nowrap text-muted`}>{formatDate(l.createdAt, true)}</td>
              <td className={td}>{l.actor?.name ?? "—"}</td>
              <td className={`${td} font-mono text-xs`}>{l.action}</td>
              <td className={`${td} text-xs`}>{l.entity}</td>
              <td className={`${td} max-w-md truncate font-mono text-xs text-muted`}>{l.meta ? JSON.stringify(l.meta) : ""}</td>
            </tr>
          ))}
        </Table>
        {!logs.length && <p className="p-8 text-center text-sm text-muted">No admin activity yet.</p>}
      </div>
    </>
  );
}
